/**
 * @local/dsh-memories — the on-disk memory store: read model and writers.
 *
 * A long-term store is a directory of `*.md` files plus an `INDEX.md`. The
 * index lists every file that carries a `Description: <one line>` line right
 * after its `# Title` heading, one line per file:
 * `- Title (file-name.md) — description`. The plugin NEVER writes INDEX.md:
 * it is generated by the repo script `scripts/generate-index.mjs` (the only
 * writer), and `loadIndexSection` composes the exact same document read-only
 * in memory when no INDEX.md exists. Writers (short-term append/compact,
 * long-term file create/update) touch memory files only. All reads are
 * bounded and fail-open; nothing here knows about cwd, sessions, or surfaces.
 */

import { mkdir, readdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { readTextIfPresent, isDirectory } from './fs.js';
import {
  WINDOWS_RESERVED_NAMES,
  globalShortTermFile,
} from './paths.js';

/** The index artifact of each long-term store; written only by the script. */
export const INDEX_FILENAME = 'INDEX.md';
/** Cap on one source memory file read, to bound work on pathological files. */
export const MAX_SOURCE_CHARS = 262144;
/** Hard ceiling for one memory description, enforced on every index surface. */
export const MAX_DESCRIPTION_CHARS = 1000;

/**
 * Header of every composed/generated INDEX.md. Defined here — next to the
 * composer both the script and the injection synthesis use — so the
 * on-disk artifact and the read-only synthesis can never drift apart.
 */
const INDEX_HEADER = '<!-- Generated by scripts/generate-index.mjs from the dsh-memories plugin. Regenerate with `node scripts/generate-index.mjs` after changing memory files; hand edits are overwritten. Files without a "Description:" line right after the heading are not listed. -->';

/**
 * Extract a memory file's title (first `# ` heading, anywhere in the file)
 * and description. The description is the `Description:` line IMMEDIATELY
 * after the heading (blank lines in between are tolerated): the first
 * non-empty line after the heading decides — anything else means the file
 * has no description and is not listed in the index.
 * @param {string} text
 * @param {string} fallbackTitle used when the file has no `# ` heading.
 * @returns {{ title: string, description: string | undefined }}
 */
export function parseMemoryMeta(text, fallbackTitle) {
  const lines = text.split(/\r?\n/);
  let title = '';
  let description;
  for (const line of lines) {
    if (title === '') {
      const heading = /^#\s+(.*)$/.exec(line);
      if (heading) title = heading[1].trim();
      continue;
    }
    const trimmed = line.trim();
    if (trimmed === '') continue;
    const described = /^Description:\s*(.*)$/.exec(trimmed);
    if (described && described[1].trim() !== '') description = described[1].trim();
    break;
  }
  return { title: title === '' ? fallbackTitle : title, description };
}

/**
 * Clamp a description for INDEX use: at most MAX_DESCRIPTION_CHARS characters
 * (the ellipsis included), never splitting a surrogate pair. Hand-edited
 * files may carry longer lines; the index shows them honestly truncated and
 * the file itself is never touched.
 * @param {string} description
 * @returns {string}
 */
export function clampDescription(description) {
  if (description.length <= MAX_DESCRIPTION_CHARS) return description;
  return `${truncateChars(description, MAX_DESCRIPTION_CHARS - 1)}…`;
}

/**
 * Validate a description on the WRITE surfaces (the memory tool and the
 * /memory command), which reject over-long or multi-line values instead of
 * truncating. A blank value is treated as "omitted" by the callers.
 * @param {unknown} description raw argument.
 * @returns {string | undefined} error message, or undefined when acceptable.
 */
export function descriptionWriteError(description) {
  if (description === undefined) return undefined;
  if (typeof description !== 'string') return 'description must be a string';
  if (/[\r\n]/.test(description)) {
    return `description must be a single line (at most ${MAX_DESCRIPTION_CHARS} characters, no line breaks)`;
  }
  const value = description.trim();
  if (value === '') return undefined;
  if (value.length > MAX_DESCRIPTION_CHARS) {
    return `description must be at most ${MAX_DESCRIPTION_CHARS} characters (got ${value.length})`;
  }
  return undefined;
}

/**
 * List the memory files (`*.md`, except the index) of a directory, sorted by name.
 * @param {string} dir
 * @param {AbortSignal} [signal]
 * @returns {Promise<readonly string[]>} file names, possibly empty.
 */
export async function listMemoryFiles(dir, signal) {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true, signal });
  } catch {
    return [];
  }
  return entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.md') && entry.name !== INDEX_FILENAME)
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b, 'en', { sensitivity: 'base' }));
}

/**
 * Compose the complete INDEX.md document of a long-term directory: header
 * comment, `# Memory index` heading, and one `- Title (file-name.md) —
 * description` line per file that HAS a description (clamped to
 * MAX_DESCRIPTION_CHARS). This is the single composition both the
 * generation script (on disk) and the injection fallback (in memory) use.
 * @param {string} dir
 * @param {AbortSignal} [signal]
 * @returns {Promise<string | undefined>} the document (no trailing newline),
 *   or undefined when the directory has no memory files at all.
 */
export async function composeIndexDocument(dir, signal) {
  const names = await listMemoryFiles(dir, signal);
  if (names.length === 0) return undefined;
  const lines = [];
  for (const name of names) {
    const text = await readTextIfPresent(join(dir, name), signal);
    if (text === undefined) continue;
    const { title, description } = parseMemoryMeta(text.slice(0, MAX_SOURCE_CHARS), name.slice(0, -'.md'.length));
    if (description === undefined) continue;
    lines.push(`- ${title} (${name}) — ${clampDescription(description)}`);
  }
  return `${INDEX_HEADER}\n\n# Memory index\n\n${lines.join('\n')}`;
}

/**
 * Load the index section of one long-term store: the on-disk INDEX.md when
 * present (non-empty), else the same document composed read-only from the
 * files — never written to disk.
 * @param {string} dir memory directory.
 * @param {AbortSignal} [signal]
 * @returns {Promise<{ text: string, generated: boolean } | undefined>}
 */
export async function loadIndexSection(dir, signal) {
  if (!(await isDirectory(dir, signal))) return undefined;
  const index = await readTextIfPresent(join(dir, INDEX_FILENAME), signal);
  const trimmed = index?.trim();
  if (trimmed !== undefined && trimmed !== '') return { text: trimmed, generated: false };
  const document = await composeIndexDocument(dir, signal);
  if (document === undefined) return undefined;
  return { text: document, generated: true };
}

/**
 * Truncate by characters, backing off so a surrogate pair is never split.
 * @param {string} value
 * @param {number} maxChars
 * @returns {string}
 */
export function truncateChars(value, maxChars) {
  if (value.length <= maxChars) return value;
  let end = Math.max(0, Math.trunc(maxChars));
  while (end > 0 && (value.charCodeAt(end) & 0xfc00) === 0xdc00) end -= 1;
  return value.slice(0, end);
}

/**
 * @param {string} title
 * @returns {string} kebab-case slug, never empty, Windows-reserved-safe.
 */
export function slugify(title) {
  const slug = title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 64)
    .replace(/-+$/g, '');
  if (slug === '') {
    const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 15);
    return `memory-${stamp}`;
  }
  return WINDOWS_RESERVED_NAMES.has(slug) ? `m-${slug}` : slug;
}

/**
 * Format a local date as `YYYY-MM-DD` — the lean default stamp for short-term
 * entries (time of day goes into the entry text only when it matters).
 * @param {Date} [date]
 * @returns {string}
 */
function dateStamp(date = new Date()) {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

/**
 * Append one date-stamped entry to the global short-term note. A pure
 * append: this NEVER trims — when a save leaves the note over
 * `shortTermMemoriesCap`, the save result directs the agent to `compact`
 * (the LLM decides entry by entry what stays, folds, or drops).
 *
 * @param {string} dshHome
 * @param {string} text
 * @returns {Promise<{ path: string, chars: number }>}
 */
export async function appendShortTerm(dshHome, text) {
  const file = globalShortTermFile(dshHome);
  await mkdir(dirname(file), { recursive: true });
  const existing = (await readTextIfPresent(file)) ?? '';
  const lines = existing.trim() === '' ? [] : existing.replace(/\r?\n$/, '').split(/\r?\n/);
  lines.push(`- [${dateStamp()}] ${text}`);
  const content = `${lines.join('\n')}\n`;
  await writeFile(file, content, 'utf8');
  return { path: file, chars: content.length };
}

/**
 * Replace the whole short-term note with compacted content (the `compact`
 * tool action); trailing newlines are normalized to exactly one.
 * @param {string} dshHome
 * @param {string} content compacted note body.
 * @returns {Promise<{ path: string, chars: number }>}
 */
export async function rewriteShortTerm(dshHome, content) {
  const file = globalShortTermFile(dshHome);
  await mkdir(dirname(file), { recursive: true });
  const text = `${content.replace(/\r?\n+$/, '')}\n`;
  await writeFile(file, text, 'utf8');
  return { path: file, chars: text.length };
}

/**
 * Create/update one long-term memory file. The file gets a `Description:`
 * line right after the heading when a description is given; an update that
 * carries none KEEPS the file's existing Description line (a write must
 * never silently de-index a memory). INDEX.md is NOT touched — the
 * generation script owns it.
 * @param {string} dir memory directory (global long-term or workspace).
 * @param {string} title memory title (becomes the `# ` heading).
 * @param {string} body memory body text.
 * @param {string | undefined} [description] one-line description, or none.
 * @returns {Promise<{ file: string }>} the written file's display-relative name.
 */
export async function writeLongTermMemory(dir, title, body, description) {
  await mkdir(dir, { recursive: true });
  const fileName = `${slugify(title)}.md`;
  const filePath = join(dir, fileName);
  let descriptionLine = '';
  if (description === undefined) {
    const existing = await readTextIfPresent(filePath);
    if (existing !== undefined) {
      const { description: kept } = parseMemoryMeta(existing.slice(0, MAX_SOURCE_CHARS), title);
      if (kept !== undefined) descriptionLine = `Description: ${kept}\n\n`;
    }
  } else {
    descriptionLine = `Description: ${description.trim()}\n\n`;
  }
  await writeFile(filePath, `# ${title}\n\n${descriptionLine}${body}\n`, 'utf8');
  return { file: fileName };
}
